import type { Prisma } from '@prisma/client';
import { prisma } from './prisma';
import { SYSTEM_CATEGORIES } from './categories';
import { addMonthsISO, currentMonthISO, monthRangeUTC } from './dates';

// What counts as spending:
//  - a card purchase counts in full on its date and category (not when it is paid off);
//  - the expense generated by a card payment (abono) does NOT count: it only moves money
//    from an account to the card debt, and the purchase was already counted.
// Debt payments still count as expenses (a loan has no purchase record of its own).

/** Filter that leaves out the expenses generated by card payments. */
export const NOT_CARD_PAYMENT: Prisma.ExpenseWhereInput = {
  category: { name: { not: SYSTEM_CATEGORIES.cardPayment.name } },
};

export interface PeriodTotals { income: number; expense: number }

/** Income and spending (expenses + card purchases) for the calendar dates in [start, end). */
export async function periodTotals(userId: string, start: Date, end: Date): Promise<PeriodTotals> {
  const range = { gte: start, lt: end };
  const [income, expense, purchases] = await Promise.all([
    prisma.income.aggregate({ where: { userId, date: range }, _sum: { amount: true } }),
    prisma.expense.aggregate({ where: { userId, date: range, ...NOT_CARD_PAYMENT }, _sum: { amount: true } }),
    prisma.cardPurchase.aggregate({ where: { userId, date: range }, _sum: { totalAmount: true } }),
  ]);
  return {
    income: income._sum.amount ?? 0,
    expense: (expense._sum.amount ?? 0) + (purchases._sum.totalAmount ?? 0),
  };
}

/**
 * Totals for the dashboard and the figures the health score is based on.
 * The score would swing wildly (and say "improve" on day 1 of every month, before the
 * salary arrives) if it only looked at the current month, so it uses the average of the
 * previous 3 complete months that have data, or the current month when there is no history.
 */
export async function dashboardTotals(userId: string, now: Date = new Date()) {
  const current = currentMonthISO(now);
  const months = [current, ...[1, 2, 3].map((n) => addMonthsISO(current, -n))];
  const [thisMonth, ...history] = await Promise.all(
    months.map((m) => {
      const { start, end } = monthRangeUTC(m);
      return periodTotals(userId, start, end);
    }),
  );

  const withData = history.filter((t) => t.income > 0 || t.expense > 0);
  const scoreBasis: PeriodTotals = withData.length === 0
    ? thisMonth
    : {
        income: withData.reduce((s, t) => s + t.income, 0) / withData.length,
        expense: withData.reduce((s, t) => s + t.expense, 0) / withData.length,
      };
  return { thisMonth, scoreBasis };
}

/** Spending per expense category (expenses + card purchases) for the dates in [start, end). */
export async function spentByCategory(userId: string, categoryIds: string[], start: Date, end: Date): Promise<Map<string, number>> {
  const spent = new Map<string, number>();
  if (categoryIds.length === 0) return spent;
  const where = { userId, categoryId: { in: categoryIds }, date: { gte: start, lt: end } };
  const [expenses, purchases] = await Promise.all([
    prisma.expense.groupBy({ by: ['categoryId'], where: { ...where, ...NOT_CARD_PAYMENT }, _sum: { amount: true } }),
    prisma.cardPurchase.groupBy({ by: ['categoryId'], where, _sum: { totalAmount: true } }),
  ]);
  for (const e of expenses) spent.set(e.categoryId, (spent.get(e.categoryId) ?? 0) + (e._sum.amount ?? 0));
  for (const p of purchases) spent.set(p.categoryId, (spent.get(p.categoryId) ?? 0) + (p._sum.totalAmount ?? 0));
  return spent;
}
